// HasDeviceWith applies the HasEdge predicate on the "device" edge with a given conditions (other predicates).
func HasDeviceWith(preds ...predicate.CameraDevice) predicate.CameraCredential {
	return predicate.CameraCredential(func(s *sql.Selector) {
		step := newDeviceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasBinding applies the HasEdge predicate on the "binding" edge.
func HasBinding() predicate.CameraCredential {
	return predicate.CameraCredential(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldId),
			sqlgraph.Edge(sqlgraph.M2O, false, BindingTable, BindingColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBindingWith applies the HasEdge predicate on the "binding" edge with a given conditions (other predicates).
func HasBindingWith(preds ...predicate.CameraBinding) predicate.CameraCredential {
	return predicate.CameraCredential(func(s *sql.Selector) {
		step := newBindingStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraCredential) predicate.CameraCredential {
	return predicate.CameraCredential(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraCredential) predicate.CameraCredential {
	return predicate.CameraCredential(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraCredential) predicate.CameraCredential {
	return predicate.CameraCredential(sql.NotPredicates(p))
}
